function settingsFailureDetails(error, operation, step) {
  const value = error;
  const data = value?.data;
  const lines = [`操作：${operation}`, `步骤：${step}`];
  if (typeof data?.code === "string")
    lines.push(`错误码：${data.code}`);
  const message = data?.message ?? value?.message;
  if (typeof message === "string")
    lines.push(`原因：${message}`);
  if (typeof data?.causeError?.message === "string" && data.causeError.message !== message)
    lines.push(`具体原因：${data.causeError.message}`);
  return lines.join(`
`);
}
function modelReadFailure(error, operation, next) {
  const details = settingsFailureDetails(error, operation, "读取 DVS 模型配置");
  return {
    message: `读取 DVS 模型配置${details.includes("超时") ? "超时" : "失败"}，${next}`,
    details
  };
}
function settingsResultState(error) {
  return error?.data?.resultState;
}

