function mountDvsConfigPanel(container, controller, requests, theme, floorData, entry) {
  const root = container.ownerDocument.createElement("div");
  container.append(root);
  const app = createApp(ConfigPanel_default, { entry, controller, requests, theme, floorData });
  app.mount(root);
  return () => {
    app.unmount();
    root.remove();
  };
}

