var MODEL_TEST_SCHEMA = {
  type: "object",
  properties: { ok: { type: "boolean" }, message: { type: "string" } },
  required: ["ok", "message"],
  additionalProperties: false
};
var MODEL_TEST_MESSAGES = [
  {
    role: "system",
    content: "这是模型连接和 JSON 格式测试。只返回 JSON 对象，包含布尔类型的 ok 和字符串类型的 message，不要输出 Markdown 围栏或额外文字。"
  },
  { role: "user", content: '请返回一个简单的 JSON 示例：{"ok":true,"message":"test"}。' }
];
function validateTestResponse(content) {
  const value = JSON.parse(content);
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("未返回 JSON 对象。");
  const result = value;
  if (Object.keys(result).length !== 2 || typeof result.ok !== "boolean" || typeof result.message !== "string")
    throw new Error("JSON 对象缺少要求的字段或字段类型不正确。");
}
